from pathlib import Path
p=Path('results/swi-prolog/tokens')
for row in (p/'TEXTS-1B-P05-P08.tsv').read_text().splitlines()[1:]:
 name=row.split('\\t')[0]
 print('\\n'+name)
 rows=[r.split('\\t',2) for r in (p/(name+'.tokens.tsv')).read_text().splitlines()[1:]]
 groups={}
 for i,l,t in rows:groups.setdefault(l,[]).append((i,t))
 for l,ts in groups.items(): print(f'{ts[0][0]}-{ts[-1][0]}: '+ ' '.join(t for i,t in ts))
PY"

