/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import json,collections
b=Path('results/swi-prolog')
for conf in ['constraints','coroutines','plain','session','tabling']:
 fs=sorted(p for prob in ['P05','P06','P07','P08'] for kind in ['raw','raw-rerun-m2'] for p in (b/conf/prob/kind).glob('*.json'))
 print(conf,len(fs),'behaviour',sum('.behaviour.' in p.name for p in fs),'reruns',sum('raw-rerun' in str(p) for p in fs))
 if conf not in ['constraints','coroutines']:continue
 for p in fs:
  x=json.loads(p.read_text())
  if x['run']['mode']"'!='"'behaviour':continue
  print('\\n',p.name,x['run']['program']['path'])
  for s in x['stages']:
   a=s['attempts'][-1]; c=a['computations'][0]
   print(s['stage'],c['execution_state']['states'],'answers',[(z['verbatim']) for q in c['queries'] for z in q['answers']], 'obs',a['observe']['raw'],'susp',c['suspended']['items'])
   if c['execution_state']['error_verbatim']:print('error',c['execution_state']['error_verbatim'])
   src=c['steps']['restart_cost_source']
   if src and 'before stage' in src: print('NOT REACHED',src)
  if x['harness_faults']:print('FAULTS',x['harness_faults'])
PY"

