/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import json
b=Path('results/swi-prolog')
for conf in ['plain','session','tabling']:
 print('\\nCONFIG',conf)
 for prob in ['P05','P06','P07','P08']:
  for p in sorted((b/conf/prob/'raw').glob('*behaviour*.json')):
   x=json.loads(p.read_text()); print(p.name,x['run']['program']['path'].split('/')[-1])
   for s in x['stages']:
    a=s['attempts'][-1];c=a['computations'][0];src=c['steps']['restart_cost_source'] or ''
    if 'before stage' in src:print(s['stage'],'NOT REACHED',c['execution_state']['states']);continue
    print(s['stage'],c['execution_state']['states'],'ans',[z['verbatim'] for q in c['queries'] for z in q['answers']],'obs',repr(a['observe']['raw']),'susp',c['suspended'])
    if c['execution_state']['error_verbatim']:print('error',c['execution_state']['error_verbatim'].split('\\n')[0])
   if x['harness_faults']:print('FAULTS',x['harness_faults'])
PY"

