/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import json,re,collections
b=Path('results/swi-prolog'); stats=collections.Counter();diff=[]
for conf in ['constraints','coroutines','plain','session','tabling']:
 files=[p for prob in ['P05','P06','P07','P08'] for p in (b/conf/prob/'raw').glob('*.json')]; data=[(p,json.loads(p.read_text())) for p in files]
 beh={(x['run']['instance'],x['run']['program']['path']):x for p,x in data if x['run']['mode']=='behaviour'}
 for p,x in data:
  stats['records']+=1;stats['stages']+=len(x['stages']);stats['invalid']+=('INVALID' in p.name)
  assert all(len(s['attempts'])==1 for s in x['stages'])
  if x['run']['mode']=='behaviour':continue
  y=beh[(x['run']['instance'],x['run']['program']['path'])]
  for s,t in zip(x['stages'],y['stages']):
   a=s['attempts'][-1];v=t['attempts'][-1];c=a['computations'][0];d=v['computations'][0]
   norm=lambda z: re.sub(r'_\\d+','_V',z)
   sig=lambda a,c:(c['execution_state']['states'],[norm(z['verbatim']) for q in c['queries'] for z in q['answers']],norm(a['observe']['raw']),c['suspended']['items'])
   if sig(a,c)"'!=sig(v,d):diff.append((str(p),s['"'stage'],sig(v,d),sig(a,c)))
print(stats,'raw differences',len(diff))
for z in diff: print(z)
for conf,prob,instance in [('session','P08','P08c'),('session','P05','P05a'),('plain','P07','P07a.321')]:
 p=next((b/conf/prob/'raw').glob(instance+'.behaviour.*.json'));x=json.loads(p.read_text()); print('\\nDETAIL',p)
 for s in x['stages']:
  a=s['attempts'][0];c=a['computations'][0]
  print(s['stage'],'STATE',c['execution_state'],'POSE',a['posed'],'OBS',a['observe'],'SEPARATE',str(a['separate_run'])[:2000])
PY"

